const body = ($input.item.json.body) || $input.item.json || {};
const E = body.empresa    || {};
const C = body.contacto   || {};
const V = body.vacante    || {};
const P = body.perfil     || {};
const S = body.estrategia || {};
const X = body.extras     || {};
const M = body.metadata   || {};

const txt = (s) => (s == null ? '' : String(s)).trim();
const arr = (a) => Array.isArray(a) ? a.filter(Boolean).map(x => String(x).trim()).join(', ') : txt(a);
const presente = (v) => Array.isArray(v) ? v.filter(Boolean).length > 0 : txt(v) !== '';

const obligatorios = {
  'Empresa': E.nombre, 'Industria': E.industria, 'Tamano': E.tamano, 'Ubicacion': E.ubicacion,
  'Contacto': C.nombre, 'Email contacto': C.email, 'Telefono': C.telefono,
  'Titulo vacante': V.titulo, 'Seniority': V.seniority, 'Modalidad': V.modalidad,
  'Tipo contratacion': V.tipo_contratacion, 'Urgencia': V.urgencia, 'Plazas': V.vacantes,
  'Skills tecnicas': P.skills_tecnicas, 'Anos experiencia': P.anos_experiencia,
  'Objetivo del rol': S.objetivo_rol, 'Retos principales': S.retos_principales
};
const claves = Object.keys(obligatorios);
const faltantes = claves.filter(k => !presente(obligatorios[k]));
const completitud = Math.round(((claves.length - faltantes.length) / claves.length) * 100);
const criticos_ok = presente(E.nombre) && presente(C.email) && presente(V.titulo);
const es_valido = criticos_ok && completitud >= 80;

const salario = (V.salario_min || V.salario_max)
  ? ('MXN ' + (V.salario_min || '?') + ' - ' + (V.salario_max || '?'))
  : 'No especificado';

const fecha = new Date().toISOString();
const req_id = (txt(E.nombre) || 'empresa') + '::' + (txt(V.titulo) || 'vacante') + '::' + Date.now();

return { json: {
  req_id,
  empresa: txt(E.nombre) || 'No especificado',
  industria: txt(E.industria) || 'No especificado',
  tamano: txt(E.tamano) || 'No especificado',
  sitio_web: txt(E.sitio_web),
  ubicacion: txt(E.ubicacion) || 'No especificado',
  contacto_nombre: txt(C.nombre) || 'No especificado',
  contacto_cargo: txt(C.cargo),
  contacto_email: txt(C.email),
  contacto_tel: txt(C.telefono),
  contacto_linkedin: txt(C.linkedin),
  titulo: txt(V.titulo) || 'No especificado',
  seniority: txt(V.seniority) || 'No especificado',
  modalidad: txt(V.modalidad) || 'No especificado',
  salario,
  tipo_contratacion: txt(V.tipo_contratacion) || 'No especificado',
  urgencia: txt(V.urgencia) || 'No especificado',
  vacantes: txt(V.vacantes) || '1',
  skills_tecnicas: arr(P.skills_tecnicas) || 'No especificado',
  soft_skills: arr(P.soft_skills) || 'No especificado',
  anos_experiencia: txt(P.anos_experiencia) || 'No especificado',
  idiomas: arr(P.idiomas) || 'No especificado',
  herramientas: arr(P.herramientas) || 'No especificado',
  certificaciones: arr(P.certificaciones) || 'No especificado',
  objetivo_rol: txt(S.objetivo_rol) || 'No especificado',
  retos_principales: txt(S.retos_principales) || 'No especificado',
  kpis: txt(S.kpis) || 'No especificado',
  estructura_equipo: txt(S.estructura_equipo) || 'No especificado',
  reporta_a: txt(S.reporta_a) || 'No especificado',
  personas_a_cargo: txt(S.personas_a_cargo) || 'No especificado',
  comentarios: txt(X.comentarios) || 'Ninguno',
  fecha_contratacion: txt(X.fecha_contratacion) || 'No especificada',
  adjunto: (X.archivo ? 'Si' : 'No'),
  source: txt(M.source) || 'hackes_jobs_web',
  form_version: txt(M.form_version) || 'v2',
  fecha,
  completitud,
  faltantes: faltantes.join('; ') || 'Ninguno',
  es_valido,
  validez_flag: es_valido ? 'COMPLETO' : 'INCOMPLETO'
}};

