const REQ=['calidad_brief','resumen_requisicion','perfil_ideal','requisitos_eliminatorios','requisitos_deseables','analisis_salarial','estrategia_atraccion','terminos_busqueda','preguntas_screening','senales_alerta','prioridad_sla'];
const errShape=(r)=>({calidad_brief:'ERROR_PARSEO',resumen_requisicion:'No se pudo leer la respuesta del modelo.',perfil_ideal:'ERROR DE PARSEO: '+r,requisitos_eliminatorios:'N/A',requisitos_deseables:'N/A',analisis_salarial:'N/A',estrategia_atraccion:'N/A',terminos_busqueda:'N/A',preguntas_screening:'N/A',senales_alerta:'Revision manual requerida.',prioridad_sla:'Revision Manual Requerida',_parse_error:r});
function extractText(r){if(r==null)return '';if(typeof r==='string')return r;const c=[r.text,r.output_text,r.response,r.message&&r.message.content,r.content&&typeof r.content==='string'?r.content:null,r.content&&r.content.parts&&r.content.parts[0]&&r.content.parts[0].text,r.candidates&&r.candidates[0]&&r.candidates[0].content&&r.candidates[0].content.parts&&r.candidates[0].content.parts[0]&&r.candidates[0].content.parts[0].text];for(const x of c)if(typeof x==='string'&&x.trim())return x;return JSON.stringify(r);}
const raw=$input.item.json;
let t;
try{
  t=extractText(raw);
  if(!t||!t.trim())return{json:errShape('Respuesta vacia')};
  t=String(t).replace(/^\s*```(?:json)?\s*/i,'').replace(/\s*```\s*$/i,'').trim();
  const a=t.indexOf('{'),b=t.lastIndexOf('}');
  const j=(a===-1||b<=a)?t:t.slice(a,b+1);
  let p;
  try{p=JSON.parse(j);}catch(_){p=JSON.parse(j.replace(/,\s*([}\]])/g,'$1'));}
  const miss=REQ.filter(k=>!(k in p));
  if(miss.length)return{json:Object.assign({},errShape('Claves faltantes: '+miss.join(',')),p,{calidad_brief:p.calidad_brief||'PARCIAL'})};
  return{json:p};
}catch(e){return{json:errShape(e.message||String(e))};}
